import sys

LEVELS = ["ERROR", "WARN", "INFO", "DEBUG"]


def main():
    if len(sys.argv) < 2:
        print("usage: prog LOGFILE", file=sys.stderr)
        return 2
    counts = {l: 0 for l in LEVELS}
    try:
        with open(sys.argv[1], encoding="utf-8", errors="replace") as f:
            for line in f:
                parts = line.split()
                if len(parts) >= 2 and parts[1] in counts:
                    counts[parts[1]] += 1
    except OSError as e:
        print(f"error: cannot read {sys.argv[1]}: {e.strerror}", file=sys.stderr)
        return 1
    for l in sorted(LEVELS, key=lambda l: (-counts[l], LEVELS.index(l))):
        if counts[l]:
            print(l, counts[l])
    return 0


