    for name in os.listdir(d):
        if pat.fullmatch(name):
            try:
                if stat.S_ISREG(os.lstat(os.path.join(d, name)).st_mode):
                    names.append(name)
            except OSError:
                pass
    names.sort()
    cut = max(len(names) - n, 0)
    gone = names[:cut]
    for name in gone:
        try:
            os.remove(os.path.join(d, name))
        except OSError as e:
            print("cannot delete %s: %s" % (name, e), file=sys.stderr)
            return 1
        print("deleted " + name)
    print("kept %d" % (len(names) - len(gone)))
    return 0

sys.exit(main())
