import os, sys, hashlib

def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py DIR\n")
        return 2
    d = sys.argv[1]
    if not os.path.isdir(d):
        sys.stderr.write("not a directory: %s\n" % d)
        return 1
    by_size = {}
    for root, dirs, files in os.walk(d):
        for f in files:
            p = os.path.join(root, f)
            if os.path.islink(p) or not os.path.isfile(p):
                continue
            rel = os.path.relpath(p, d).replace(os.sep, "/")
            try:
                by_size.setdefault(os.path.getsize(p), []).append((rel, p))
            except OSError:
                pass
    groups = []
    for size, items in by_size.items():
        if len(items) < 2:
            continue
        h = {}
        for rel, p in items:
            try:
                m = hashlib.sha256()
                with open(p, "rb") as fh:
                    for c in iter(lambda: fh.read(1 << 20), b""):
                        m.update(c)
            except OSError:
                continue
            h.setdefault(m.digest(), []).append(os.fsencode(rel))
        for g in h.values():
            if len(g) > 1:
                groups.append(sorted(g))
    groups.sort()
    out = b"\n\n".join(b"\n".join(g) for g in groups)
    if out:
        sys.stdout.buffer.write(out + b"\n")
    return 0

sys.exit(main())
