        for f in fn:
            p = os.path.join(dp, f)
            try:
                st = os.lstat(p)
            except OSError:
                continue
            if not stat.S_ISREG(st.st_mode):
                continue
            rel = os.path.relpath(p, root).replace(os.sep, "/")
            by_size.setdefault(st.st_size, []).append((rel, p))
