cat > solution.sh <<'EOF'
#!/bin/bash
exec python3 -I -c '
import sys, json
d = {}
skipped = 0
for raw in sys.stdin.buffer.read().split(b"\n"):
    try:
        line = raw.decode("utf-8")
    except UnicodeDecodeError:
        skipped += 1
        continue
    if not line.strip():
        continue
    try:
        o = json.loads(line)
    except Exception:
        skipped += 1
        continue
    if not isinstance(o, dict):
        skipped += 1
        continue
    e = o.get("endpoint"); m = o.get("ms")
    if not isinstance(e, str) or type(m) is not int or m < 0:
        skipped += 1
        continue
    d.setdefault(e, []).append(m)
out = []
for e in sorted(d, key=lambda s: s.encode("utf-8", "surrogatepass")):
    v = sorted(d[e]); n = len(v)
    p = lambda P: v[(P * n + 99) // 100 - 1]
    out.append("%s count=%d p50=%d p95=%d" % (e, n, p(50), p(95)))
if skipped:
    out.append("skipped %d" % skipped)
sys.stdout.buffer.write(("\n".join(out) + "\n" if out else "").encode("utf-8", "surrogatepass"))
'
EOF
